@extends('layouts.app') @section('content')<h2>Bobot Optimasi Multi-Kriteria</h2><p class="text-muted">Atur kepentingan setiap kriteria. Total bobot harus tepat 100.</p><div class="card p-4"><form method="POST" action="{{ route('weights.update') }}">@csrf @method('PUT')@foreach($weights as $w)<div class="row align-items-center mb-3"><div class="col-md-4"><label class="form-label fw-semibold">{{ str_replace('_',' ',ucfirst($w->criterion)) }}</label><div class="small text-muted">{{ $w->description }}</div></div><div class="col-md-3"><div class="input-group"><input type="number" min="0" max="100" step="1" class="form-control weight-input" name="weights[{{ $w->id }}]" value="{{ $w->weight }}" required><span class="input-group-text">%</span></div></div></div>@endforeach<div class="alert alert-info">Total bobot saat ini: <strong id="total">0</strong>%</div><button class="btn btn-primary">Simpan Bobot</button></form></div>@endsection @push('scripts')<script>function sum(){let n=0;document.querySelectorAll('.weight-input').forEach(x=>n+=Number(x.value||0));document.getElementById('total').textContent=n;}document.querySelectorAll('.weight-input').forEach(x=>x.addEventListener('input',sum));sum();</script>@endpush